// Do not edit this file by hand.
// It is generated by `mesh build` from the entity files; change them and rebuild.
// Mesh's own file: `bind`, the default binding and `transaction`. Import `#mesh` for them, and `#mesh/domain/<module>`
// for a module's action functions; each of those calls through `$delegate` here.
// Mesh's own imports and internal names carry a `$` so that no entity or action name can collide with them.

import {
  composer as $makeComposer,
  FrameworkError as $FrameworkError,
  type BindOptions as $BindOptions,
  type ContextArgument as $ContextArgument,
  type DataLayer as $DataLayer,
} from "@meshfw/runtime";
import { bindEvent, bindEventReads } from "./domain/audit/event.actions";
import { bindAttempt, bindAttemptReads } from "./domain/execution/attempt.actions";
import { bindInvocation, bindInvocationReads } from "./domain/execution/invocation.actions";
import { bindMachine, bindMachineReads } from "./domain/execution/machine.actions";
import { bindRun, bindRunReads } from "./domain/execution/run.actions";
import {
  bindSessionReference,
  bindSessionReferenceReads,
} from "./domain/execution/sessionReference.actions";
import { bindCollaborator, bindCollaboratorReads } from "./domain/identity/collaborator.actions";
import { bindMembership, bindMembershipReads } from "./domain/identity/membership.actions";
import { bindWorkspace, bindWorkspaceReads } from "./domain/identity/workspace.actions";
import { bindAssignment, bindAssignmentReads } from "./domain/work/assignment.actions";
import { bindClaim, bindClaimReads } from "./domain/work/claim.actions";
import { bindCompletion, bindCompletionReads } from "./domain/work/completion.actions";
import { bindDependency, bindDependencyReads } from "./domain/work/dependency.actions";
import {
  bindEvidenceReference,
  bindEvidenceReferenceReads,
} from "./domain/work/evidenceReference.actions";
import { bindLateResult, bindLateResultReads } from "./domain/work/lateResult.actions";
import { bindReview, bindReviewReads } from "./domain/work/review.actions";
import { bindSubmission, bindSubmissionReads } from "./domain/work/submission.actions";
import { bindTask, bindTaskReads } from "./domain/work/task.actions";
import type { Actions, Reads } from "./composition";

/**
 * Every action function, bound to `layer`, and `transaction`. Opens nothing and creates no table:
 * the caller owns the layer and closes it.
 */ export function bind(layer: $DataLayer, options: $BindOptions = {}) {
  // `actions` and `tx` in a function of an entity file come from this composer, which holds this binding's functions.
  const $composer = $makeComposer(layer);
  const eventActions = bindEvent(layer, options, $composer);
  const eventReads = bindEventReads(layer, options);
  const attemptActions = bindAttempt(layer, options, $composer);
  const attemptReads = bindAttemptReads(layer, options);
  const invocationActions = bindInvocation(layer, options, $composer);
  const invocationReads = bindInvocationReads(layer, options);
  const machineActions = bindMachine(layer, options, $composer);
  const machineReads = bindMachineReads(layer, options);
  const runActions = bindRun(layer, options, $composer);
  const runReads = bindRunReads(layer, options);
  const sessionReferenceActions = bindSessionReference(layer, options, $composer);
  const sessionReferenceReads = bindSessionReferenceReads(layer, options);
  const collaboratorActions = bindCollaborator(layer, options, $composer);
  const collaboratorReads = bindCollaboratorReads(layer, options);
  const membershipActions = bindMembership(layer, options, $composer);
  const membershipReads = bindMembershipReads(layer, options);
  const workspaceActions = bindWorkspace(layer, options, $composer);
  const workspaceReads = bindWorkspaceReads(layer, options);
  const assignmentActions = bindAssignment(layer, options, $composer);
  const assignmentReads = bindAssignmentReads(layer, options);
  const claimActions = bindClaim(layer, options, $composer);
  const claimReads = bindClaimReads(layer, options);
  const completionActions = bindCompletion(layer, options, $composer);
  const completionReads = bindCompletionReads(layer, options);
  const dependencyActions = bindDependency(layer, options, $composer);
  const dependencyReads = bindDependencyReads(layer, options);
  const evidenceReferenceActions = bindEvidenceReference(layer, options, $composer);
  const evidenceReferenceReads = bindEvidenceReferenceReads(layer, options);
  const lateResultActions = bindLateResult(layer, options, $composer);
  const lateResultReads = bindLateResultReads(layer, options);
  const reviewActions = bindReview(layer, options, $composer);
  const reviewReads = bindReviewReads(layer, options);
  const submissionActions = bindSubmission(layer, options, $composer);
  const submissionReads = bindSubmissionReads(layer, options);
  const taskActions = bindTask(layer, options, $composer);
  const taskReads = bindTaskReads(layer, options);
  const $functions = Object.freeze({
    recordEvent: eventActions.record,
    readEvent: eventActions.read,
    startAttempt: attemptActions.start,
    finishAttempt: attemptActions.finish,
    reportStoppedAttempt: attemptActions.reportStopped,
    abandonAttempt: attemptActions.abandon,
    readAttempt: attemptActions.read,
    recordInvocation: invocationActions.record,
    correctInvocation: invocationActions.correct,
    readInvocation: invocationActions.read,
    registerMachine: machineActions.register,
    reportMachine: machineActions.report,
    updateMachine: machineActions.update,
    retireMachine: machineActions.retire,
    readMachine: machineActions.read,
    startRun: runActions.start,
    cancelRun: runActions.cancel,
    settleRun: runActions.settle,
    readRun: runActions.read,
    recordSessionReference: sessionReferenceActions.record,
    setAvailabilitySessionReference: sessionReferenceActions.setAvailability,
    redactSessionReference: sessionReferenceActions.redact,
    readSessionReference: sessionReferenceActions.read,
    registerCollaborator: collaboratorActions.register,
    updateCollaborator: collaboratorActions.update,
    retireCollaborator: collaboratorActions.retire,
    readCollaborator: collaboratorActions.read,
    grantMembership: membershipActions.grant,
    changeRoleMembership: membershipActions.changeRole,
    revokeMembership: membershipActions.revoke,
    readMembership: membershipActions.read,
    createWorkspace: workspaceActions.create,
    renameWorkspace: workspaceActions.rename,
    readWorkspace: workspaceActions.read,
    startAssignment: assignmentActions.start,
    finishAssignment: assignmentActions.finish,
    readAssignment: assignmentActions.read,
    acquireClaim: claimActions.acquire,
    renewClaim: claimActions.renew,
    releaseClaim: claimActions.release,
    revokeClaim: claimActions.revoke,
    expireClaim: claimActions.expire,
    endClaim: claimActions.end,
    readClaim: claimActions.read,
    recordCompletion: completionActions.record,
    readCompletion: completionActions.read,
    addDependency: dependencyActions.add,
    removeDependency: dependencyActions.remove,
    readDependency: dependencyActions.read,
    recordEvidenceReference: evidenceReferenceActions.record,
    readEvidenceReference: evidenceReferenceActions.read,
    recordLateResult: lateResultActions.record,
    readLateResult: lateResultActions.read,
    acceptReview: reviewActions.accept,
    returnReview: reviewActions.return,
    readReview: reviewActions.read,
    submitSubmission: submissionActions.submit,
    withdrawSubmission: submissionActions.withdraw,
    settleSubmission: submissionActions.settle,
    recordAcceptedSubmission: submissionActions.recordAccepted,
    readSubmission: submissionActions.read,
    createTask: taskActions.create,
    updateTask: taskActions.update,
    setPriorityTask: taskActions.setPriority,
    moveTask: taskActions.move,
    reopenTask: taskActions.reopen,
    touchTask: taskActions.touch,
    cancelTask: taskActions.cancel,
    completeTask: taskActions.complete,
    assignTask: taskActions.assign,
    unassignTask: taskActions.unassign,
    readTask: taskActions.read,
  });
  $composer.provide($functions, {
    readEvent: eventReads.read,
    readAttempt: attemptReads.read,
    readInvocation: invocationReads.read,
    readMachine: machineReads.read,
    readRun: runReads.read,
    readSessionReference: sessionReferenceReads.read,
    readCollaborator: collaboratorReads.read,
    readMembership: membershipReads.read,
    readWorkspace: workspaceReads.read,
    readAssignment: assignmentReads.read,
    readClaim: claimReads.read,
    readCompletion: completionReads.read,
    readDependency: dependencyReads.read,
    readEvidenceReference: evidenceReferenceReads.read,
    readLateResult: lateResultReads.read,
    readReview: reviewReads.read,
    readSubmission: submissionReads.read,
    readTask: taskReads.read,
  });
  return Object.freeze({
    ...$functions,
    /**
     * Open a transaction, or join the running one, and call `fn` with every action function and every read bound to it.
     * Resolves with what `fn` resolves with. A call through them that fails fails the transaction, even when `fn` catches it.
     */
    transaction<T>(
      fn: (composition: { readonly actions: Actions; readonly tx: Reads }) => Promise<T>,
      ...[context]: $ContextArgument
    ): Promise<T> {
      return $composer.transaction(
        (composition) =>
          fn(composition as unknown as { readonly actions: Actions; readonly tx: Reads }),
        context,
      );
    },
  });
}

let $defaultBinding: ReturnType<typeof bind> | undefined;
let $defaultLayer: $DataLayer | undefined;
let $disconnecting: Promise<void> | undefined;
/** Calls through the top-level functions that have not settled; `disconnect()` waits for them. */
let $inFlight = 0;
const $idle: (() => void)[] = [];

function $isDataLayer(value: unknown): value is $DataLayer {
  return (
    typeof value === "object" &&
    value !== null &&
    typeof (value as Partial<$DataLayer>).transaction === "function" &&
    typeof (value as Partial<$DataLayer>).refuseIfFailed === "function" &&
    typeof (value as Partial<$DataLayer>).close === "function"
  );
}

/**
 * Bind every action function to the data layer `mesh.config.ts` configures. The
 * layer opens on the first transaction. Waits for a `disconnect()` in progress;
 * throws `FrameworkError` while connected.
 */
export async function connect(): Promise<void> {
  if ($disconnecting) await $disconnecting;
  if ($defaultLayer)
    throw new $FrameworkError("connect() was called while connected; call disconnect() first");
  const { default: config } = await import("../mesh.config");
  const data: unknown = config.data;
  if (!$isDataLayer(data))
    throw new $FrameworkError(
      `The data adapter "${config.data.name}" configured in mesh.config.ts has no run-time half: connect() needs a data layer with transaction(), refuseIfFailed() and close()`,
    );
  if ($defaultLayer)
    throw new $FrameworkError("connect() was called while connected; call disconnect() first");
  $defaultBinding = bind(data);
  $defaultLayer = data;
}

/**
 * Stop new calls, wait for the calls already made through the top-level functions to
 * settle, however long they take, then close the layer `connect()` bound. Does nothing
 * when not connected. If `close()` rejects, the binding is restored and the program
 * stays connected, so `disconnect()` can be called again. Never closes a layer passed
 * to `bind`.
 */
export async function disconnect(): Promise<void> {
  if ($disconnecting) return $disconnecting;
  const layer = $defaultLayer;
  const binding = $defaultBinding;
  if (!layer || !binding) return;
  $defaultBinding = undefined;
  $defaultLayer = undefined;
  $disconnecting = (async () => {
    while ($inFlight > 0) await new Promise<void>((resolve) => $idle.push(resolve));
    try {
      await layer.close();
    } catch (error) {
      $defaultBinding = binding;
      $defaultLayer = layer;
      throw error;
    }
  })();
  try {
    await $disconnecting;
  } finally {
    $disconnecting = undefined;
  }
}

/**
 * Run one call on the default binding, counted so that `disconnect()` waits for it. Every action function a module's
 * `index.ts` exports is one such call; it is Mesh's, and `#mesh` does not re-export it.
 */
export async function $delegate<T>(
  name: string,
  call: (binding: ReturnType<typeof bind>) => Promise<T>,
): Promise<T> {
  if (!$defaultBinding)
    throw new $FrameworkError(
      `${name} was called while not connected: call connect() first, or use bind(db) with a data layer of your own`,
    );
  $inFlight++;
  try {
    return await call($defaultBinding);
  } finally {
    $inFlight--;
    if ($inFlight === 0) for (const resolve of $idle.splice(0)) resolve();
  }
}

/**
 * Open a transaction on the connected layer, or join the running one, and call `fn({ actions, tx })`: every action
 * function and every read, bound to it, carrying `context` unless a call passes its own. Resolves with what `fn`
 * resolves with. A call through `actions` or `tx` that fails fails the whole transaction, even when `fn` catches it.
 */
export async function transaction<T>(
  fn: (composition: { readonly actions: Actions; readonly tx: Reads }) => Promise<T>,
  ...context: $ContextArgument
): Promise<T> {
  return $delegate("transaction", (binding) => binding.transaction(fn, ...context));
}
